mapper.select:
select b.batch_id as "batchId", b.paper_id as "paperId", p.paper_name as "paperName", b.file_name as "fileName", b.success_rows as "successRows", b.fail_rows as "failRows", b.create_by as "createBy", b.create_time as "createTime" from spas_score_batch b left join spas_paper p on p.paper_id = b.paper_id where ( exists ( select 1 from spas_score_detail sd join spas_student s on s.student_id = sd.student_id left join sys_dept d on s.dept_id = d.dept_id where sd.batch_id = b.batch_id
) or exists ( select 1 from spas_paper p2 left join sys_dept d on p2.dept_id = d.dept_id where p2.paper_id = b.paper_id
AND p2.dept_id in #{did}
${scope.params.dataScope}
) ) order by b.batch_id desc limit #{limit}

select ( (select count(*) from spas_paper_question q join spas_paper p on p.paper_id = q.paper_id left join sys_dept d on p.dept_id = d.dept_id where not exists (select 1 from spas_question_knowledge qk where qk.question_id = q.question_id)
) + (select count(*) from spas_paper p left join sys_dept d on p.dept_id = d.dept_id where p.exam_date is null
) )
